def is_prime(n: int) -> bool:
    """Return whether n is prime."""
    # Handle trivial cases
    if n < 2:
        return False
    if n in (2, 3):
        return True
    # Even numbers greater than 2 are composite
    if n % 2 == 0:
        return False
    # Check odd divisors up to sqrt(n)
    limit = int(n ** 0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True
EOF

